export async function clearAsOf(page: Page): Promise<void> {
  await page.getByTestId('asof-clear').click();
  await expect(page.getByTestId('sheet-asof')).toHaveText('', { timeout: LOAD_WAIT });
}

// ---- people ----------------------------------------------------------------------------------

export function row(page: Page, personId: string): Locator {
  return page.getByTestId(`person-row-${personId}`);
}

function rows(page: Page): Locator {
  return page.locator('[data-testid^="person-row-"]');
}

function rowsNamed(page: Page, name: string): Locator {
  const re = new RegExp(`^\\s*${escapeRe(name.trim())}(\\s\\([^()]*\\))?\\s*$`, 'i');
  return rows(page).filter({ has: page.getByTestId('person-name').filter({ hasText: re }) });
}

/** The id of the (newest) person row showing this name. */
export async function personId(page: Page, name: string): Promise<string> {
  const r = rowsNamed(page, name).last();
  await expect(r).toBeVisible({ timeout: WAIT });
  return idOf(await r.getAttribute('data-testid'), 'person-row-');
}

type PersonFields = { name?: string; grade?: string; gradeFrom?: string; terms?: string; termsFrom?: string; contact?: string; tags?: string };

/** Fill the person form. `clear` (an add) also empties every optional field the test does not
 *  give, so nothing typed for a refused add carries into this one; an edit leaves the
 *  fields it is not given as the editor filled them. */
async function fillPersonForm(page: Page, f: PersonFields, clear = false) {
  if (f.name !== undefined) await page.getByTestId('person-form-name').fill(f.name);
  if (f.grade !== undefined) await page.getByTestId('person-form-grade').selectOption(f.grade);
  for (const [key, testid] of [['gradeFrom', 'person-form-grade-from'], ['terms', 'person-form-terms'],
    ['termsFrom', 'person-form-terms-from'], ['contact', 'person-form-contact'], ['tags', 'person-form-tags']] as const) {
    const v = f[key];
    if (v !== undefined) await page.getByTestId(testid).fill(v);
    else if (clear) await setField(page, testid, undefined);
  }
}

/** Add a person through the form. The new row's id, or null when the form refused. */
export async function addPerson(page: Page, f: PersonFields & { name: string; grade: string }): Promise<string | null> {
  const before = await ids(rows(page), 'person-row-');
  await fillPersonForm(page, f, true);
  await page.getByTestId('person-form-submit').click();
  let added: string | null = null;
  const ok = await until(page, async () => (added = await addedPerson(page, before, f.name)) !== null,
    page.getByTestId('person-form-error'), 'add person');
  return ok ? added : null;
}

export async function editOpen(page: Page, personId: string): Promise<void> {
  await page.getByTestId(`person-edit-${personId}`).click();
  await expect(page.getByTestId('person-form-name')).not.toHaveValue('', { timeout: WAIT });
  editing.set(page, personId);
}

/**
 * Save the open editor with these changes; true when saved, false when the form refused. `shows` is
 * the grade the row shows once saved: by default the grade entered, but a grade dated from another
 * day may leave the grade in force on the sheet's today unchanged.
 */
type Shows = string | { grade?: string; terms?: string };

export async function editSave(page: Page, f: PersonFields, shows?: Shows): Promise<boolean> {
  const id = editing.get(page);
  if (!id) throw new Error('editSave without editOpen');
  const want = typeof shows === 'string' ? { grade: shows } : (shows ?? {});
  const grade = want.grade ?? f.grade;                       // the grade the row shows once saved
  const terms = want.terms ?? f.terms;                       // the terms in force the row shows
  const r = row(page, id);
  const shows_ = async () => {
    if (f.name !== undefined && plainName(await shown(r.getByTestId('person-name'))) !== f.name.trim()) return false;
    if (grade !== undefined && await shown(r.getByTestId('person-grade')) !== grade) return false;
    if (terms !== undefined && await shown(r.getByTestId('person-terms')) !== terms) return false;
    return !(await page.getByTestId('person-form-error').isVisible().catch(() => false));
  };
  // a save the row cannot show (the values it checks are already there) is judged by its error
  const already = await shows_();
  await fillPersonForm(page, f);
  await page.getByTestId('person-form-submit').click();
  return until(page, shows_, page.getByTestId('person-form-error'), 'save person', already);
}

export async function editPerson(page: Page, personId: string, f: PersonFields, shows?: Shows): Promise<boolean> {
  await editOpen(page, personId);
  return editSave(page, f, shows);
}

export async function retire(page: Page, personId: string, date: string): Promise<boolean> {
  const r = row(page, personId);
  const done = async () => (await r.count()) === 0 || await shown(r.getByTestId('person-retired')) === 'yes';
  const already = await done();
  await r.getByTestId('person-retire-date').fill(date);
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Claim } from './claims';
import { Session } from './session';

export const GRADES = ['A', 'B', 'C'] as const;

export interface Person {
  id: number;
  name: string;
  grade: string;
  /** Moved on by each save; an edit made from an older version is refused. */
  version: number;
  /** How many statements were taken of them. */
  statementCount: number;
  /** The last statement's due-total, two decimals or n/a; null before their first. */
  statedTotal: string | null;
  /** The sheet's today when the last statement was taken; null before their first. */
  statementDate: string | null;
  /** Whether a retirement date is set: then they count as retired at once, whatever the date. */
  retired: boolean;
  /** The date they are retired from (YYYY-MM-DD); null while not retired. */
  retiredFrom: string | null;
  /** On hold: their OPEN claims count in no live total; their SETTLED ones still do. */
  held: boolean;
  /** The ids of the other people on the sheet they have named as their patrons. */
  patronIds: number[];
}

/** A person after a statement, with their claims as it bound them, newest first. */
export interface Statement {
  person: Person;
  claims: Claim[];
}

/** A refused save: why, and the person as stored now when someone else saved them first. */
export interface Refusal {
  error: string;
  current?: Person;
}

export interface PersonFields {
  name: string;
  grade: string;
}

// The people on the active sheet, in the order they were added, re-read from the server each
// time the sheet is loaded.
@Injectable({ providedIn: 'root' })
export class People {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly people = signal<Person[]>([]);
  /** Whether the list shows retired people; belongs to the screen, so loading a sheet leaves it. */
  readonly showRetired = signal(false);
  private loads = 0;

  /** Re-read the active sheet's people from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.people.set([]);
    if (!user || !sid) return null;
    try {
      const people = await firstValueFrom(
        this.http.get<Person[]>(this.url(sid), { headers: { 'X-User': user } }),
      );
      if (load === this.loads) this.people.set(people);
      return null;
    } catch (e) {
      return failed('load', e).replace(' person', ' people');
    }
  }

  /** Add a person; an error message when refused. */
  async add(f: PersonFields): Promise<string | null> {
    const refused = this.check(f);
    if (refused) return refused;
    const sid = this.session.sheetId()!;
    try {
      const person = await firstValueFrom(
        this.http.post<Person>(this.url(sid), this.body(f), { headers: { 'X-User': this.session.user()! } }),
      );
      if (this.session.sheetId() === sid) this.people.update((ps) => [...ps, person]);
      return null;
    } catch (e) {
      return failed('add', e);
    }
  }

  /** Change a person's name and grade, from the version the editor loaded; the refusal when
   *  refused, carrying the person as stored now when someone else saved them in the meantime. */
  async update(id: number, version: number, f: PersonFields): Promise<Refusal | null> {
    const refused = this.check(f);
    if (refused) return { error: refused };
    const sid = this.session.sheetId()!;
    const put = (person: Person) => {
      if (this.session.sheetId() === sid) this.people.update((ps) => ps.map((p) => (p.id === id ? person : p)));
    };
    try {
      put(
        await firstValueFrom(
          this.http.put<Person>(`${this.url(sid)}/${id}`, { ...this.body(f), version }, {
            headers: { 'X-User': this.session.user()! },
          }),
        ),
      );
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 412) {
        const current = e.error as Person;
        put(current);
        return { error: 'Someone else has changed this person. Their values are shown; review and save again.', current };
      }
      return { error: failed('save', e) };
    }
  }

  /** Take a person's statement: the person and their claims as it left them, or an error message
   *  when refused. */
  async statement(id: number): Promise<Statement | string> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    try {
      const stated = await firstValueFrom(
        this.http.post<Statement>(`${this.url(sid)}/${id}/statement`, null, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) {
        this.people.update((ps) => ps.map((p) => (p.id === id ? stated.person : p)));
      }
      return stated;
    } catch (e) {
      return failed('take statement of', e);
    }
  }

  /** Retire a person from a date (blank takes the sheet's today); an error message when refused. */
  async retire(id: number, from: string): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    const d = from.trim();
    if (d && !/^\d{4}-\d{2}-\d{2}$/.test(d)) return 'Enter a date as YYYY-MM-DD.';
    try {
      const person = await firstValueFrom(
        this.http.post<Person>(`${this.url(sid)}/${id}/retire`, { from: d || null }, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.people.update((ps) => ps.map((p) => (p.id === id ? person : p)));
      return null;
    } catch (e) {
      return failed('retire', e);
    }
  }

  /** Put a person on hold, or take them off it; an error message when refused. */
  async toggleHold(id: number): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    try {
      const person = await firstValueFrom(
        this.http.post<Person>(`${this.url(sid)}/${id}/hold`, null, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.people.update((ps) => ps.map((p) => (p.id === id ? person : p)));
      return null;
    } catch (e) {
      return failed('hold', e);
    }
  }

  /** Name another person on the sheet as a person's patron; an error message when refused. */
  async addPatron(id: number, patronId: number): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    if (patronId === id) return 'A person cannot be their own patron.';
    try {
      const person = await firstValueFrom(
        this.http.post<Person>(`${this.url(sid)}/${id}/patrons`, { patronId }, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.people.update((ps) => ps.map((p) => (p.id === id ? person : p)));
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 409) {
        const err: unknown = e.error;
        if (err && typeof err === 'object' && 'message' in err && typeof err.message === 'string') return err.message;
      }
      return failed('add patron to', e);
    }
  }

  private check(f: PersonFields): string | null {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    if (!f.name.trim()) return 'Enter a name.';
    if (!(GRADES as readonly string[]).includes(f.grade)) return 'Choose a grade.';
    return null;
  }

  private body(f: PersonFields): PersonFields {
    return { name: f.name.trim(), grade: f.grade };
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}/people`;
  }
}

function failed(what: string, e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 409) return 'That name is already in use.';
  return e instanceof HttpErrorResponse ? `Could not ${what} person (${e.status}).` : `Could not ${what} person.`;
}

