export class PersonClaims {
  protected readonly claims = inject(Claims);
  private readonly rates = inject(Rates);
  protected readonly periods = inject(Periods);
  readonly personId = input.required<number>();
  /** The person's grade, whose rate in force on each claim's date gives its due, unless fixed when
   *  it was settled or bound by the person's last statement. */
  readonly grade = input.required<string>();
  protected readonly list = computed(() => this.claims.of(this.personId()));
  protected readonly amount = signal('');
  protected readonly date = signal('');
  protected readonly note = signal('');
  /** The id of the claim whose editor is open, or null when the form adds. */
  protected readonly editing = signal<number | null>(null);
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  protected readonly actions: { action: ClaimAction; label: string }[] = [
    { action: 'open', label: 'Open' },
    { action: 'settle', label: 'Settle' },
    { action: 'void', label: 'Void' },
  ];
  /** The id of the claim whose status change is under way. */
  protected readonly acting = signal<number | null>(null);
  /** The last refused status change, or edit of a claim that is no longer a DRAFT, shown on its claim
   *  until the next action on that claim. */
  protected readonly actionError = signal<{ id: number; message: string } | null>(null);

  /** The claim's due: fixed when settled, else as its person's last statement bound it, else live; an
   *  overdue claim's late charge on top of the bound or live figure. */
  protected figure(c: Claim): string {
    if (c.settledDue !== null) return c.settledDue;
    const f = c.stated
      ? (c.statedDue === null ? null : hundredths(c.statedDue))
      : this.rates.dueCents(hundredths(c.amount), this.grade(), c.date);
    return f === null ? NO_RATE : money(f + this.claims.lateCents(c, f));
  }

  protected fid(field: string): string {
    return `claim-form-${field}-${this.personId()}`;
  }
  protected readonly saving = signal(false);
  /** The period whose action is under way, and the last action's refusal, by period. */
  protected readonly acting = signal<number | null>(null);
  protected readonly actionError = signal<{ id: number; message: string } | null>(null);

  /** Each period's due-total, by period id: the figures of the claims that count live whose date falls
   *  in it — a settled claim's frozen due, else as its person's last statement bound it, else its
   *  live due, an overdue claim's late charge on top (a claim with no figure adds nothing). */
  protected readonly dueTotals = computed(() => {
    const grades = new Map(this.people.people().map((p) => [p.id, p.grade]));
    const sums = new Map<number, bigint>();
    for (const c of this.claims.live()) {
      const period = this.periods.of(c.date);
      if (!period) continue;
      let due: bigint | null;
      if (c.settledDue !== null) due = hundredths(c.settledDue);
      else if (c.stated) due = c.statedDue === null ? null : hundredths(c.statedDue);
      else {
        const grade = grades.get(c.personId);
        due = grade === undefined ? null : this.rates.dueCents(hundredths(c.amount), grade, c.date);
      }
      if (due !== null && c.settledDue === null) due += this.claims.lateCents(c, due);
      sums.set(period.id, (sums.get(period.id) ?? 0n) + (due ?? 0n));
    }
    return new Map([...sums].map(([id, sum]) => [id, money(sum)]));
  });

